.radar-feed-pill--replay { border-color: var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); }
.radar-tenant { padding-left: 16px; border-left: 1px solid var(--radar-line); font-size: 13px; font-weight: 600; letter-spacing: 1px; color: var(--radar-muted); }
/* a narrower screen drops what it can read elsewhere: the tenant (console header), the subtitle, then the UTC clock */
@media (max-width: 1280px) { .radar-tenant { display: none; } }
@media (max-width: 1040px) { .radar-clock--utc { display: none; } .radar-head { gap: 14px; padding: 10px 16px; } }

.radar-main { flex-grow: 1; display: grid; grid-template-columns: minmax(340px, 470px) minmax(0, 1fr); gap: clamp(28px, 4vw, 72px); padding: 24px 32px 28px; min-height: 0; }
