import { useEffect, useState, type CSSProperties } from "react";
import { createTranslator } from "@dcortex/canvas-format";
import type { ApiClient } from "../api/client.js";
import { messages } from "../i18n/messages.js";
import { AuthModal } from "./AuthModal.js";
import { chooseLocale, localeOptions, readStoredLocale, writeStoredLocale } from "../viewerLocale.js";
import { NEUTRAL_MARK, parseBrand, type Brand } from "../brand.js";

/** Pre-auth marketing homepage (legacy SimpleLanding parity) — a cinematic dark hero with the
 * brand, the tenant's language pill, a light/dark toggle, and a glowing Login CTA that opens the
 * AuthModal. Locale + theme are LOCAL state here (there is no server presentation context
 * before sign-in); after login the console takes over the server-echoed context. Mounted at
 * /login, so the api client routes every unauthenticated request to this homepage.
 *
 * A tenant with a brand (knowledge-base/features/tenant-branding.md) gets the airline's photograph as a band across the top, its
 * white wordmark over it, and the headline on a card overlapping the band's lower edge. The photographs are wide and modest in
 * resolution, so they are a band rather than a full-bleed background: nothing is stretched and the aircraft stays in frame.
 * A tenant without one shows its name and the neutral dCortex mark. */
export function Landing({ client, onLoggedIn, ssoStartPath }: { client: ApiClient; onLoggedIn: () => void; ssoStartPath?: string }) {
  const [locale, setLocale] = useState<string>(client.presentation()?.locale ?? "en");
  // The tenant's languages come from the public tenant info — the page renders before any session exists.
  const [languages, setLanguages] = useState<{ code: string; label: string }[]>([]);
  const [brand, setBrand] = useState<Brand | undefined>(undefined);
  const [customerName, setCustomerName] = useState("");
  const [wordmarkFailed, setWordmarkFailed] = useState<string[]>([]);
  const [logoFailed, setLogoFailed] = useState(false);
  const [heroFailed, setHeroFailed] = useState(false);
  useEffect(() => {
    let live = true;
    client.get<{ customerName?: unknown; supportedLocales?: unknown; defaultLocale?: unknown; brand?: unknown }>("/api/auth/tenant").then(
      (info) => {
        if (!live) return;
        setBrand(parseBrand(info?.brand));
        if (typeof info?.customerName === "string") setCustomerName(info.customerName);
        const supported = Array.isArray(info?.supportedLocales) ? info.supportedLocales.filter((l): l is string => typeof l === "string") : [];
        if (supported.length === 0) return;
        setLanguages(localeOptions(supported));
        const chosen = chooseLocale(readStoredLocale(), supported, typeof info.defaultLocale === "string" ? info.defaultLocale : supported[0]!);
        setLocale(chosen);
        client.setPresentationOverride({ locale: chosen });
      },
      () => {}, // no toggle without the tenant's list; the copy stays in the default
    );
    return () => {
      live = false;
    };
  }, [client]);
  const pickLocale = (code: string) => {
    setLocale(code);
    client.setPresentationOverride({ locale: code });
    writeStoredLocale(code);
  };
  const [theme, setTheme] = useState<"dark" | "light">(
    () => (document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark"),
  );
  const [modalOpen, setModalOpen] = useState(false);
  const t = createTranslator(locale, messages);

  const toggleTheme = () => {
    const next = theme === "dark" ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", next);
    setTheme(next);
  };

  const branded = Boolean(brand?.hero || brand?.wordmark || brand?.wordmarkWhite);
  const hero = brand?.hero;
  const brandLabel = customerName || t("landing.brand");
  // The white wordmark belongs on the dark page and the airline's own colours on the light one; a page never gets the other's.
  const wordmark = theme === "light" ? brand?.wordmark : brand?.wordmarkWhite;

  return (
    <div className={branded ? "landing landing--branded" : "landing"}>
      <div className="landing-bar landing-bar-top" aria-hidden="true" />
      <div className="landing-bar landing-bar-bottom" aria-hidden="true" />

      {branded && hero && !heroFailed && (
        <div
          className="landing-ambient"
          aria-hidden="true"
          style={{ backgroundImage: `url("${hero.url}")`, "--landing-focal": hero.focal ?? "50% 50%" } as CSSProperties}
        />
      )}

      {branded && hero && (
        <div
          className="landing-band"
          role="img"
          aria-label={hero.alt ?? brandLabel}
          style={{ "--landing-focal": hero.focal ?? "50% 50%" } as CSSProperties}
        >
          {!heroFailed && <img src={hero.url} alt="" decoding="async" fetchPriority="high" onError={() => setHeroFailed(true)} />}
        </div>
      )}

      <header className="landing-header">
        <div className="landing-brand">
          {branded && wordmark && !wordmarkFailed.includes(wordmark) ? (
            <img className="landing-wordmark" src={wordmark} alt={brandLabel} onError={() => setWordmarkFailed((f) => [...f, wordmark])} />
          ) : (
            <>
              <img
                className="landing-logo-img"
                src={branded && brand?.logo && !logoFailed ? brand.logo : NEUTRAL_MARK}
                alt={branded ? "" : t("landing.logoAlt")}
                onError={() => setLogoFailed(true)}
              />
              <span>{brandLabel}</span>
            </>
          )}
        </div>
        <div className="landing-controls">
          {languages.length > 1 && (
            <span className="landing-lang">
              {languages.map((l) => (
                <button key={l.code} type="button" className={l.code === locale ? "on" : ""} onClick={() => pickLocale(l.code)}>
                  {l.label}
                </button>
              ))}
            </span>
          )}
          <button type="button" className="landing-theme" aria-label={t("landing.toggleTheme")} onClick={toggleTheme}>
            {theme === "dark" ? "☀" : "☾"}
          </button>
        </div>
      </header>

      <main className="landing-hero">
        <h1 className="landing-title">{t("landing.headingMain")}</h1>
        <div className="landing-accent">{t("landing.headingAccent")}</div>
        <p className="landing-body">{t("landing.body")}</p>
        <button type="button" className="landing-cta" onClick={() => setModalOpen(true)}>
          {t("landing.loginCta")} <span aria-hidden="true">→</span>
        </button>
        {/* Work OS: Google SSO — a full-page redirect to the BFF's OIDC start route (default-deny: shown only when wired). */}
        {ssoStartPath && (
          <button type="button" className="landing-cta landing-sso" data-testid="sso-google" onClick={() => { window.location.href = ssoStartPath; }}>
            Sign in with Google
          </button>
        )}
      </main>

      {branded && (
        <footer className="landing-powered">
          <img src={NEUTRAL_MARK} alt="" />
          <span>{t("shell.poweredBy")}</span>
        </footer>
      )}

      {modalOpen && <AuthModal client={client} t={t} onClose={() => setModalOpen(false)} onLoggedIn={onLoggedIn} />}
    </div>
  );
}

